// Generates src/skills/agentSkills.generated.ts from the skills listed in
// agent-skills.json, taken from mapbox/mapbox-agent-skills at the pinned
// commit. That repo is the only copy of the skills; this file is gitignored
// and rebuilt by `npm run prepare` (which `npm ci` and `npm run build` run),
// so the published package carries the skills and nothing is fetched at
// runtime. It skips the download when the generated file already matches
// agent-skills.json.

import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import {
  existsSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync
} from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const configPath = join(root, 'agent-skills.json');
const outPath = join(root, 'src', 'skills', 'agentSkills.generated.ts');

const configText = readFileSync(configPath, 'utf8');
const config = JSON.parse(configText);
const configHash = createHash('sha256').update(configText).digest('hex');
const stamp = `// agent-skills.json sha256: ${configHash}`;

if (!/^[0-9a-f]{40}$/.test(config.ref)) {
  throw new Error(
    `agent-skills.json "ref" must be a full commit SHA, got "${config.ref}"`
  );
}

if (existsSync(outPath) && readFileSync(outPath, 'utf8').includes(stamp)) {
  process.exit(0);
}

// Supporting files the model can read. evals/ is for testing the skill and
// AGENTS.md is a condensed copy for other assistants, so neither is served.
const SKIPPED = new Set(['evals', 'AGENTS.md']);

function readSkillFiles(dir, base = dir, files = {}) {
  const entries = readdirSync(dir, { withFileTypes: true }).sort((a, b) =>
    a.name.localeCompare(b.name)
  );
  for (const entry of entries) {
    if (dir === base && SKIPPED.has(entry.name)) continue;
    const path = join(dir, entry.name);
    if (entry.isDirectory()) {
      readSkillFiles(path, base, files);
    } else if (entry.isFile()) {
      const bytes = readFileSync(path);
      const rel = relative(base, path).split(sep).join('/');
      // Fails on anything that isn't UTF-8 text.
      files[rel] = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
    } else {
      throw new Error(`Unsupported file in skill: ${path}`);
    }
  }
  return files;
}

const url = `https://codeload.github.com/${config.repo}/tar.gz/${config.ref}`;
const response = await fetch(url);
if (!response.ok) {
  throw new Error(
    `Fetching skills from ${url} failed: ${response.status} ${response.statusText}`
  );
}

const work = mkdtempSync(join(tmpdir(), 'agent-skills-'));
try {
  const archive = join(work, 'skills.tar.gz');
  writeFileSync(archive, Buffer.from(await response.arrayBuffer()));
  execFileSync('tar', ['-xzf', archive, '-C', work]);
  const [top] = readdirSync(work, { withFileTypes: true }).filter((e) =>
    e.isDirectory()
  );

  const skills = Object.entries(config.skills).map(([name, tools]) => {
    const dir = join(work, top.name, 'skills', name);
    if (!existsSync(join(dir, 'SKILL.md'))) {
      throw new Error(`${config.repo}@${config.ref} has no skill "${name}"`);
    }
    return { name, tools, files: readSkillFiles(dir) };
  });

  const source = `${config.repo}@${config.ref}`;
  writeFileSync(
    outPath,
    `// Generated by scripts/fetch-agent-skills.mjs from ${source}.\n` +
      `// Do not edit: change the skills there and the pin in agent-skills.json.\n` +
      `${stamp}\n\n` +
      `import type { Skill } from './Skill.js';\n\n` +
      `export const AGENT_SKILLS_SOURCE = ${JSON.stringify(source)};\n\n` +
      `export const AGENT_SKILLS: readonly Skill[] = ${JSON.stringify(skills, null, 2)};\n`
  );
  console.log(
    `Generated ${relative(root, outPath)}: ${skills.map((s) => s.name).join(', ')} from ${source}`
  );
} finally {
  rmSync(work, { recursive: true, force: true });
}
